export interface Brief {
  /** Leaf ID as given in the brief: S001…S170 (with -1/-2/-3 splits) or EXT-I09…EXT-I20. */
  id: string;
  /** The original catalogue ID this page covers (S059 for S059-1), or null for an extension. */
  catalogueId: string | null;
  /** Catalogue entry name, when the page is a split of a broader entry. */
  catalogueName?: string;
  family: string;
  title: string;
  proposedRoute: string;
  module: string;
  focus: string;
  blueprint: string;
  /** Per-tier scope overrides from the brief (the "leaf overrides"). */
  tiers?: [string, string, string];
  /** Public tier names given by the brief, when it gives them. */
  tierNames?: [string, string, string];
  proof: string;
  acceptance: string;
  /** Discovery URL the catalogue entry came from. Internal evidence only; never proof of a provider's quality. */
  source?: string;
  /** Industry extensions only. */
  industry?: { workflow: string; roles: string; records: string; relatedIds: string[] };
}

type Opt = Partial<Pick<Brief, 'tiers' | 'catalogueName' | 'tierNames' | 'industry'>>;
const L = (id: string, family: string, title: string, slug: string, module: string, focus: string, blueprint: string, proof: string, acceptance: string, source: string, opt: Opt = {}): Brief => ({
  id,
  catalogueId: id.startsWith('EXT') ? null : id.split('-')[0]!,
  family,
  title,
  proposedRoute: slug.startsWith('/') ? slug : `/services/${slug}`,
  module,
  focus,
  blueprint,
  proof,
  acceptance,
  source,
  ...opt,
});

