export const getBrief = (id: string) => briefs.find((b) => b.id === id);
export const getFamily = (code: string) => families.find((f) => f.code === code);
export const moduleAnchor = (b: Brief) => b.module.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
export const moduleLink = (b: Brief) => `${getFamily(b.family)!.demo.route}#${moduleAnchor(b)}`;
